export function evaluate({ inputs, time }) {
  const u = Number(inputs.launchSpeed ?? 4);
  const g = Number(inputs.gravity ?? 9.8);
  const m = Number(inputs.mass ?? 1.0);

  const tApex = u / g;
  const yApex = (u * u) / (2 * g);
  const tEnd = 2 * tApex;

  const clampedT = Math.max(0, Math.min(time, tEnd));
  const v = u - g * clampedT;
  const y = u * clampedT - 0.5 * g * clampedT * clampedT;
  const Fg = m * g;
  const a = -g;

  let stateText = 'Ready to toss';
  if (clampedT > 0 && Math.abs(v) > 0.05) {
    if (v > 0) stateText = 'Rising';
    else stateText = 'Falling';
  } else if (clampedT > 0 && Math.abs(v) <= 0.05) {
    stateText = 'At the top';
  }
  if (clampedT >= tEnd - 0.001) {
    stateText = 'Back at launch height';
  }

  const objects = [];

  // Panel 1: Motion
  const p1 = sdk.panel({ x: 10, y: 10, w: 300, h: 400, title: 'The motion', state: stateText, id: 'lane.motion' });
  objects.push(...p1);

  const yAxis = sdk.axis('axis.y', {
    x: 75,
    y: 370,
    length: 310,
    orientation: 'y',
    min: 0,
    max: 2.2,
    ticks: [0, 0.5, 1.0, 1.5, 2.0],
    label: 'Height',
    unit: 'm'
  });
  objects.push(yAxis);

  const ballYPx = 370 - (y / 2.2) * 310;
  const ballXPx = 150;

  const ball = sdk.circle('ball.toss', ballXPx, ballYPx, 24);
  objects.push(ball);

  const vVec = sdk.vector('vec.v', { x: ballXPx - 25, y: ballYPx }, {
    value: v,
    direction: 'up',
    scale: 15,
    label: 'v'
  });
  objects.push(...vVec);

  const aVec = sdk.vector('vec.a', { x: ballXPx + 25, y: ballYPx }, {
    value: a,
    direction: 'up',
    scale: 12,
    label: 'a'
  });
  objects.push(...aVec);

  const calloutLines = [
    `v = ${sdk.format(v, 2)} m/s`,
    `a = ${sdk.format(a, 1)} m/s²`,
    `Fg = ${sdk.format(Fg, 1)} N`
  ];
  const callout = sdk.callout(ballXPx + 55, ballYPx - 30, calloutLines, { id: 'callout.toss' });
  objects.push(...callout);

  // Panel 2: Velocity Graph
  const p2 = sdk.panel({ x: 330, y: 10, w: 300, h: 400, title: 'Velocity over time', state: `a = -${sdk.format(g, 1)} m/s²`, id: 'lane.graph' });
  objects.push(...p2);

  const numPoints = 21;
  const seriesPoints = [];
  for (let i = 0; i < numPoints; i++) {
    const tSample = (tEnd * i) / (numPoints - 1);
    const vSample = u - g * tSample;
    seriesPoints.push({ x: tSample, y: vSample });
  }

  const vtPlot = sdk.plot('plot.vt', {
    x: 340,
    y: 50,
    w: 280,
    h: 340,
    axes: {
      x: { label: 'Time', min: 0, max: 1.8, unit: 's' },
      y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' }
    },
    series: [
      {
        label: 'v(t)',
        kind: 'line',
        points: seriesPoints
      }
    ]
  });
  objects.push(vtPlot);

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: 'velocity', value: v },
        { id: 'acceleration', value: a },
        { id: 'force', value: Fg },
        { id: 'motionState', value: stateText }
      ]
    },
    quantities: {
      launchSpeed: u,
      gravity: g,
      mass: m,
      apexTime: tApex,
      apexHeight: yApex,
      height: y,
      velocity: v,
      acceleration: a,
      force: Fg
    }
  };
}
